  +    tool: d.source ? `lsp:${sanitizeDiagnosticMessage(d.source)}` : "lsp",
  +    ...(toolVersion ? { toolVersion } : {}),
  +    ...(d.code !== undefined && d.code !== null ? { code: sanitizeDiagnosticMessage(d.code) } : {}),
  +    severity: d.severity,
  +    file,
  +    line: d.range.start.line + 1,
