  +export type VersionProbe = (tool: string, workspace: string) => string | null;
  +
  +function readJsonVersion(file: string): string | null {
  +  try {
  +    const v = JSON.parse(fs.readFileSync(file, "utf-8"))?.version;
  +    return typeof v === "string" ? v : null;
  +  } catch {
  +    return null;
  +  }
  +}
